<?xml version="1.0" encoding="UTF-8"?>
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">
    <modelVersion>4.0.0</modelVersion>

    <groupId>com.example</groupId>
    <artifactId>app</artifactId>
    <version>0.1.0-SNAPSHOT</version>
    <packaging>jar</packaging>

    <properties>
        <maven.compiler.release>25</maven.compiler.release>
        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>

        <lombok.version>1.18.48</lombok.version>
        <junit.version>5.13.4</junit.version>
        <maven-compiler-plugin.version>3.14.0</maven-compiler-plugin.version>
        <maven-surefire-plugin.version>3.5.3</maven-surefire-plugin.version>
    </properties>

    <dependencies>
        <!-- Lombok: compile-time only, not shipped with the artifact -->
        <dependency>
            <groupId>org.projectlombok</groupId>
            <artifactId>lombok</artifactId>
            <version>${lombok.version}</version>
            <scope>provided</scope>
        </dependency>

        <dependency>
            <groupId>org.junit.jupiter</groupId>
            <artifactId>junit-jupiter</artifactId>
            <version>${junit.version}</version>
            <scope>test</scope>
        </dependency>
    </dependencies>

    <build>
        <plugins>
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-compiler-plugin</artifactId>
                <version>${maven-compiler-plugin.version}</version>
                <configuration>
                    <!-- JDK 23+ no longer runs annotation processors found on the
                         classpath implicitly, so Lombok must be declared here. -->
                    <annotationProcessorPaths>
                        <path>
                            <groupId>org.projectlombok</groupId>
                            <artifactId>lombok</artifactId>
                            <version>${lombok.version}</version>
                        </path>
                    </annotationProcessorPaths>
                </configuration>
            </plugin>
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-surefire-plugin</artifactId>
                <version>${maven-surefire-plugin.version}</version>
            </plugin>
        </plugins>
    </build>
</project>
EOF
cat > lombok.config <<'EOF'
# Stop Lombok from looking for config files in parent directories
config.stopBubbling = true
# Mark generated code so coverage tools (JaCoCo etc.) ignore it
lombok.addLombokGeneratedAnnotation = true
# Make @EqualsAndHashCode/@Data on subclasses include superclass fields explicitly
lombok.equalsAndHashCode.callSuper = warn
EOF
cat > src/main/java/com/example/model/User.java <<'EOF'
package com.example.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Mutable entity example: {@code @Data} generates getters, setters,
 * {@code equals}/{@code hashCode} and {@code toString}.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class User {
    private Long id;
    private String name;
    private String email;
}
EOF
cat > src/main/java/com/example/model/Money.java <<'EOF'
package com.example.model;

import lombok.NonNull;
import lombok.Value;

import java.math.BigDecimal;

/**
 * Immutable value example: {@code @Value} makes fields private final and
 * generates getters, an all-args constructor, {@code equals}/{@code hashCode}
 * and {@code toString}. For simple data carriers, a Java {@code record} is
 * also a good boilerplate-free option.
 */
@Value
public class Money {
    @NonNull BigDecimal amount;
    @NonNull String currency;
}
EOF
cat > src/test/java/com/example/model/LombokTest.java <<'EOF'
package com.example.model;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class LombokTest {

    @Test
    void userHasGeneratedAccessorsBuilderAndEquality() {
        User user = User.builder().id(1L).name("Ada").email("ada@example.com").build();
        user.setName("Ada Lovelace");

        assertEquals("Ada Lovelace", user.getName());
        assertEquals(new User(1L, "Ada Lovelace", "ada@example.com"), user);
    }

    @Test
    void moneyIsImmutableAndNullChecked() {
        Money money = new Money(new BigDecimal("9.99"), "EUR");

        assertEquals("EUR", money.getCurrency());
        assertThrows(NullPointerException.class, () -> new Money(null, "EUR"));
    }
}
EOF
cat > .gitignore <<'EOF'
target/
.idea/
*.iml
.vscode/
.classpath
.project
.settings/
EOF
mvn -q -B verify 2>&1 | tail -30; echo EXIT=$?

